-- R4-CURE (VEIL-22), the chair's addition (2): every function 211 and 212 create or restate, at the tip, on a chain of
-- 001..212 (212 applied over 211), with its declared volatility and the reason it is what it is. The salt's reach is
-- computed over EVERY public function: a function draws the salt (its body calls gen_random_uuid()), carries it (an
-- argument named salt), or reaches it (its body calls, by name, a function that draws or reaches it; transitively).
\pset footer off
\pset pager off
with recursive f as (
  select p.oid, p.proname, p.oid::regprocedure::text as sig, p.provolatile, p.prosrc, l.lanname, p.prosecdef, coalesce(p.proargnames, '{}') as args
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace join pg_language l on l.oid = p.prolang where n.nspname = 'public'),
e as (select distinct a.proname as caller, b.proname as callee from f a join f b on a.proname <> b.proname and a.prosrc ~ ('(^|[^a-z0-9_])' || b.proname || '\s*\(')),
draws as (select distinct proname from f where prosrc ilike '%gen_random_uuid%' and proname like '\_gallery%'),
reach(proname) as (select proname from draws union select e.caller from e join reach r on e.callee = r.proname)
select f.sig as function,
       case when f.proname in ('_gallery_apply_member_overrides','_gallery_veil','_gallery_veil_apply','_gallery_veil_card','_gallery_veil_card_id','_gallery_veil_cards','_gallery_veil_clandestine','_gallery_veil_copy_bound','_gallery_veil_criminal','_gallery_veil_drop_hooks','_gallery_veil_facet','_gallery_veil_grouping','_gallery_veil_groupings','_gallery_veil_hideable','_gallery_veil_hideable_p','_gallery_veil_house','_gallery_veil_illegal_brokerage','_gallery_veil_inst_id','_gallery_veil_join','_gallery_veil_jslen','_gallery_veil_jsstr','_gallery_veil_kind_order','_gallery_veil_kinds','_gallery_veil_lower','_gallery_veil_map','_gallery_veil_map_list','_gallery_veil_npc_house','_gallery_veil_npc_id','_gallery_veil_npc_pass','_gallery_veil_num_inf','_gallery_veil_num_zero','_gallery_veil_numstr','_gallery_veil_or','_gallery_veil_own_id','_gallery_veil_parse','_gallery_veil_resolve','_gallery_veil_served','_gallery_veil_slug','_gallery_veil_snake','_gallery_veil_str','_gallery_veil_truthy','get_gallery_dossier','get_gallery_map','get_unlisted_dossier','import_gallery_dossier') and f.proname in ('_gallery_apply_member_overrides','_gallery_veil','_gallery_veil_apply','_gallery_veil_card','_gallery_veil_case_fold','_gallery_veil_cast','_gallery_veil_each_minus_at','_gallery_veil_embeds','_gallery_veil_fold','_gallery_veil_hidden_name','_gallery_veil_holders','_gallery_veil_member_revealed','_gallery_veil_minus_at','_gallery_veil_name_bound','_gallery_veil_name_case','_gallery_veil_name_floor','_gallery_veil_name_fold','_gallery_veil_name_hit','_gallery_veil_name_hits','_gallery_veil_name_json','_gallery_veil_name_near','_gallery_veil_name_needle','_gallery_veil_name_pad','_gallery_veil_name_prep','_gallery_veil_name_ready','_gallery_veil_name_search','_gallery_veil_name_sep','_gallery_veil_name_sweep','_gallery_veil_name_taken','_gallery_veil_name_tokens','_gallery_veil_named','_gallery_veil_pieces','_gallery_veil_rekey','_gallery_veil_rekey_at','_gallery_veil_rekey_each','_gallery_veil_rekey_id','_gallery_veil_rekey_ref','_gallery_veil_rekey_served','_gallery_veil_roster_members','_gallery_veil_roster_splice','_gallery_veil_runs','_gallery_veil_second_homes','_gallery_veil_sources','_gallery_veil_tie_pieces','_gallery_veil_tie_roles','_gallery_veil_withhold_always','get_gallery_dossier','get_unlisted_dossier','import_gallery_dossier') then '211, 212 restates' when f.proname in ('_gallery_apply_member_overrides','_gallery_veil','_gallery_veil_apply','_gallery_veil_card','_gallery_veil_case_fold','_gallery_veil_cast','_gallery_veil_each_minus_at','_gallery_veil_embeds','_gallery_veil_fold','_gallery_veil_hidden_name','_gallery_veil_holders','_gallery_veil_member_revealed','_gallery_veil_minus_at','_gallery_veil_name_bound','_gallery_veil_name_case','_gallery_veil_name_floor','_gallery_veil_name_fold','_gallery_veil_name_hit','_gallery_veil_name_hits','_gallery_veil_name_json','_gallery_veil_name_near','_gallery_veil_name_needle','_gallery_veil_name_pad','_gallery_veil_name_prep','_gallery_veil_name_ready','_gallery_veil_name_search','_gallery_veil_name_sep','_gallery_veil_name_sweep','_gallery_veil_name_taken','_gallery_veil_name_tokens','_gallery_veil_named','_gallery_veil_pieces','_gallery_veil_rekey','_gallery_veil_rekey_at','_gallery_veil_rekey_each','_gallery_veil_rekey_id','_gallery_veil_rekey_ref','_gallery_veil_rekey_served','_gallery_veil_roster_members','_gallery_veil_roster_splice','_gallery_veil_runs','_gallery_veil_second_homes','_gallery_veil_sources','_gallery_veil_tie_pieces','_gallery_veil_tie_roles','_gallery_veil_withhold_always','get_gallery_dossier','get_unlisted_dossier','import_gallery_dossier') then '212' else '211' end as made_by,
       case f.provolatile when 'i' then 'IMMUTABLE' when 's' then 'STABLE' else 'VOLATILE' end as volatility,
       case when f.proname in (select proname from draws) then 'DRAWS the read''s salt (gen_random_uuid()): VOLATILE, so no plan folds or caches it'
            when 'salt' = any(f.args) then 'CARRIES the salt (argument salt): VOLATILE, so no plan folds a call of it with constant arguments'
            when f.proname in (select proname from reach) then 'REACHES the salt through ' || (select string_agg(callee, ', ' order by callee) from e where caller = f.proname and callee in (select proname from reach)) || ': VOLATILE'
            when f.provolatile = 'i' then 'no salt: a pure function of its arguments (no table, no session state): IMMUTABLE as stated'
            when f.provolatile = 's' then 'no salt: reads tables or the caller (auth.uid(), settings) within one snapshot: STABLE as stated'
            else 'no salt: VOLATILE as stated (it writes, or is a plpgsql default)' end as reason
  from f where f.proname in ('_gallery_apply_member_overrides','_gallery_veil','_gallery_veil_apply','_gallery_veil_card','_gallery_veil_card_id','_gallery_veil_cards','_gallery_veil_clandestine','_gallery_veil_copy_bound','_gallery_veil_criminal','_gallery_veil_drop_hooks','_gallery_veil_facet','_gallery_veil_grouping','_gallery_veil_groupings','_gallery_veil_hideable','_gallery_veil_hideable_p','_gallery_veil_house','_gallery_veil_illegal_brokerage','_gallery_veil_inst_id','_gallery_veil_join','_gallery_veil_jslen','_gallery_veil_jsstr','_gallery_veil_kind_order','_gallery_veil_kinds','_gallery_veil_lower','_gallery_veil_map','_gallery_veil_map_list','_gallery_veil_npc_house','_gallery_veil_npc_id','_gallery_veil_npc_pass','_gallery_veil_num_inf','_gallery_veil_num_zero','_gallery_veil_numstr','_gallery_veil_or','_gallery_veil_own_id','_gallery_veil_parse','_gallery_veil_resolve','_gallery_veil_served','_gallery_veil_slug','_gallery_veil_snake','_gallery_veil_str','_gallery_veil_truthy','get_gallery_dossier','get_gallery_map','get_unlisted_dossier','import_gallery_dossier') or f.proname in ('_gallery_apply_member_overrides','_gallery_veil','_gallery_veil_apply','_gallery_veil_card','_gallery_veil_case_fold','_gallery_veil_cast','_gallery_veil_each_minus_at','_gallery_veil_embeds','_gallery_veil_fold','_gallery_veil_hidden_name','_gallery_veil_holders','_gallery_veil_member_revealed','_gallery_veil_minus_at','_gallery_veil_name_bound','_gallery_veil_name_case','_gallery_veil_name_floor','_gallery_veil_name_fold','_gallery_veil_name_hit','_gallery_veil_name_hits','_gallery_veil_name_json','_gallery_veil_name_near','_gallery_veil_name_needle','_gallery_veil_name_pad','_gallery_veil_name_prep','_gallery_veil_name_ready','_gallery_veil_name_search','_gallery_veil_name_sep','_gallery_veil_name_sweep','_gallery_veil_name_taken','_gallery_veil_name_tokens','_gallery_veil_named','_gallery_veil_pieces','_gallery_veil_rekey','_gallery_veil_rekey_at','_gallery_veil_rekey_each','_gallery_veil_rekey_id','_gallery_veil_rekey_ref','_gallery_veil_rekey_served','_gallery_veil_roster_members','_gallery_veil_roster_splice','_gallery_veil_runs','_gallery_veil_second_homes','_gallery_veil_sources','_gallery_veil_tie_pieces','_gallery_veil_tie_roles','_gallery_veil_withhold_always','get_gallery_dossier','get_unlisted_dossier','import_gallery_dossier')
 order by (f.proname in (select proname from reach) or 'salt' = any(f.args)) desc, 1;
\echo == THE PROOF: functions (of every public function) that draw, carry or reach the salt and are IMMUTABLE or STABLE (none wanted)
with recursive f as (select p.proname, p.provolatile, p.prosrc, coalesce(p.proargnames, '{}') as args from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public'),
e as (select distinct a.proname as caller, b.proname as callee from f a join f b on a.proname <> b.proname and a.prosrc ~ ('(^|[^a-z0-9_])' || b.proname || '\s*\(')),
reach(proname) as (select proname from f where prosrc ilike '%gen_random_uuid%' and proname like '\_gallery%' union select e.caller from e join reach r on e.callee = r.proname)
select count(*) filter (where provolatile in ('i', 's')) as reaching_and_not_volatile, count(*) as reaching_or_carrying,
       string_agg(proname || '=' || provolatile::text, ', ' order by proname) as each
  from (select distinct proname, provolatile from f where proname in (select proname from reach) or 'salt' = any(args)) x;
